// Agent 插件 → 工作台服务 /core/*（Spec 20.3）。
// - 请求头 Authorization: Bearer <LB_TOKEN>；只连 127.0.0.1。
// - 开发模式按契约校验请求和返回（T7 步骤 3）；校验不过记日志并按 INVALID_ARGUMENT / INTERNAL 处理。
// - 连不上、服务未启动：返回 SERVICE_UNAVAILABLE（Spec 20.1）。
import { coreId, validate } from './contracts.ts'

export type CoreCommand = 'task/begin' | 'context' | 'tool' | 'progress' | 'task/end'
export type CoreResult<T = unknown> = { ok: true; value: T } | { ok: false; error: { code: string; message: string } }

export interface Endpoint { port: number; token: string }
export type EndpointSource = () => Endpoint | undefined
export type Logger = (level: 'info' | 'warn' | 'error', event: string, meta?: Record<string, unknown>) => void

export const MESSAGES = {
  SERVICE_UNAVAILABLE: '工作台服务未启动，请稍后重试',
  INVALID_ARGUMENT: '请求参数有误',
  INTERNAL: '内部错误，请重试；多次出现请联系技术支持',
} as const

const SCHEMA_NAME: Record<CoreCommand, string> = {
  'task/begin': 'task_begin', context: 'context', tool: 'tool', progress: 'progress', 'task/end': 'task_end',
}

export class CoreClient {
  constructor(
    private readonly endpoint: EndpointSource,
    private readonly log: Logger,
    private readonly validateContracts = true,
    private readonly timeoutMs = 60_000,
  ) {}

  async call<T = unknown>(command: CoreCommand, body: Record<string, unknown>): Promise<CoreResult<T>> {
    const id = coreId(SCHEMA_NAME[command])
    if (this.validateContracts) {
      const errs = validate(id, 'request', body)
      if (errs.length) {
        this.log('error', 'core.request_contract', { command, errors: errs })
        return { ok: false, error: { code: 'INVALID_ARGUMENT', message: MESSAGES.INVALID_ARGUMENT } }
      }
    }
    const ep = this.endpoint()
    if (!ep) return { ok: false, error: { code: 'SERVICE_UNAVAILABLE', message: MESSAGES.SERVICE_UNAVAILABLE } }
    const started = Date.now()
    let res: Response
    try {
      res = await fetch(`http://127.0.0.1:${ep.port}/core/${command}`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', authorization: `Bearer ${ep.token}` },
        body: JSON.stringify(body),
        redirect: 'error',
        signal: AbortSignal.timeout(this.timeoutMs),
      })
    } catch {
      this.log('warn', 'core.unreachable', { command })
      return { ok: false, error: { code: 'SERVICE_UNAVAILABLE', message: MESSAGES.SERVICE_UNAVAILABLE } }
    }
    let payload: unknown
    try { payload = await res.json() } catch { payload = undefined }
    // 日志只记元数据：命令、状态码、耗时、错误码（Spec 4.5）
    const code = (payload as CoreResult | undefined)?.ok === false ? (payload as { error: { code: string } }).error.code : undefined
    this.log('info', 'core.call', { command, status: res.status, ms: Date.now() - started, ...(code ? { code } : {}) })
    if (res.status === 401) return { ok: false, error: { code: 'SERVICE_UNAVAILABLE', message: MESSAGES.SERVICE_UNAVAILABLE } }
    if (payload === undefined) return { ok: false, error: { code: 'INTERNAL', message: MESSAGES.INTERNAL } }
    if (this.validateContracts) {
      const errs = validate(id, 'response', payload)
      if (errs.length) {
        this.log('error', 'core.response_contract', { command, errors: errs })
        return { ok: false, error: { code: 'INTERNAL', message: MESSAGES.INTERNAL } }
      }
    }
    return payload as CoreResult<T>
  }
}

// 界面 → Host → 工作台服务 /api/* 的路由表（Spec 4.3 表、20.5；T13 执行令 Q6）。
// 方法名 = 契约文件名驼峰；一个文件对应两个 HTTP 方法时加 get / put / post 前缀。
// settings、connection_test 两个文件沿用 T7 的方法（getSettings、putSettings、testConnection），不在本表。
// 每个方法只收一个参数 request（对 GET 即查询参数），路径里的 {x} 从 request 同名字段取出。

export type HttpMethod = 'GET' | 'PUT' | 'POST'

export interface ApiRoute {
  /** 远程方法名（ctx.remote.lawbench.<method>）。 */
  readonly method: string
  readonly http: HttpMethod
  /** 服务端路径；{x} 由 request.x 填入（并从查询参数、请求体里去掉）。 */
  readonly path: string
  /** 契约文件名（contracts/api/<contract>.schema.json）。 */
  readonly contract: string
  /** 不校验、不发送 request（GET 胶囊配置：契约的 request 是 PUT 的请求体）。 */
  readonly noRequest?: boolean
  /** request 里还必须有的字段（契约 request 为 GET、POST 共用时，POST 另要的字段）。 */
  readonly require?: readonly string[]
  /** 超时（毫秒）；复制、生成类接口给长一些。 */
  readonly timeoutMs?: number
}

const LONG = 10 * 60_000
const INVOICE = 35 * 60_000

export const API_ROUTES: readonly ApiRoute[] = [
  { method: 'caseOpen', http: 'POST', path: '/api/case/open', contract: 'case_open' },
  { method: 'caseRecent', http: 'GET', path: '/api/case/recent', contract: 'case_recent' },
  // 契约 1.4：从最近案件里移除（服务只删登记，案件文件夹不动）。界面经 Host 的 caseForget（按位置找登记）调它，不直接调
  { method: 'forgetCase', http: 'POST', path: '/api/case/forget', contract: 'case_forget' },
  { method: 'materialsScan', http: 'POST', path: '/api/materials/scan', contract: 'materials_scan', timeoutMs: LONG },
  { method: 'materialsImport', http: 'POST', path: '/api/materials/import', contract: 'materials_import', timeoutMs: LONG },
  { method: 'materialsRelocate', http: 'POST', path: '/api/materials/relocate', contract: 'materials_relocate', timeoutMs: LONG },
  { method: 'materialsList', http: 'GET', path: '/api/materials', contract: 'materials_list' },
  // 契约 1.4/1.5：复制材料移到回收站，引用材料只取消登记；两种情况都由服务清派生数据
  { method: 'materialsRemove', http: 'POST', path: '/api/materials/remove', contract: 'materials_remove', timeoutMs: LONG },
  // T31：界面在原生 Session.beginSubmission 生成 R 后，把本批材料预绑定到同一 R；Agent 在 task/begin 原子 claim
  { method: 'requestScope', http: 'POST', path: '/api/request/scope', contract: 'request_scope' },
  { method: 'ocrSubmit', http: 'POST', path: '/api/ocr/jobs', contract: 'ocr_submit' },
  { method: 'ocrList', http: 'GET', path: '/api/ocr/jobs', contract: 'ocr_list' },
  { method: 'ocrCancel', http: 'POST', path: '/api/ocr/jobs/{job_id}/cancel', contract: 'ocr_cancel' },
  { method: 'taskCreate', http: 'POST', path: '/api/task', contract: 'task_create' },
  // 契约 1.2：读该会话当前的选择（界面每次显示之前读，不在本地记）
  { method: 'taskCurrent', http: 'GET', path: '/api/task/current', contract: 'task_current' },
  { method: 'pipelineRun', http: 'POST', path: '/api/pipeline/run', contract: 'pipeline_run' },
  { method: 'pipelineStatus', http: 'GET', path: '/api/pipeline/{task_id}', contract: 'pipeline_status' },
  { method: 'pipelineCancel', http: 'POST', path: '/api/pipeline/{task_id}/cancel', contract: 'pipeline_cancel' },
  { method: 'tasksList', http: 'GET', path: '/api/tasks', contract: 'tasks_list' },
  { method: 'redline', http: 'POST', path: '/api/redline', contract: 'redline', timeoutMs: LONG },
  // T39：只经本机 Host 转工作台服务，再由服务走律所 6000D；界面不直连模型 provider
  { method: 'promptRefine', http: 'POST', path: '/api/prompt/refine', contract: 'prompt_refine' },
  { method: 'getWikiSuggestions', http: 'GET', path: '/api/wiki/suggestions', contract: 'wiki_suggestions' },
  { method: 'postWikiSuggestions', http: 'POST', path: '/api/wiki/suggestions/{id}', contract: 'wiki_suggestions', require: ['id', 'accept'] },
  // 契约 1.4：wiki 的核对状态记在案件里（换电脑也一致）。GET 读；POST 把当前这一版记为已核对
  { method: 'getWikiReview', http: 'GET', path: '/api/wiki/review', contract: 'wiki_review' },
  { method: 'postWikiReview', http: 'POST', path: '/api/wiki/review', contract: 'wiki_review' },
  // 契约 1.2（N35 ⑥）：本案已确认的成果（成果/索引.json）
  { method: 'outputsList', http: 'GET', path: '/api/outputs', contract: 'outputs_list' },
  { method: 'outputsConfirm', http: 'POST', path: '/api/outputs/confirm', contract: 'outputs_confirm', timeoutMs: LONG },
  // 契约 1.6：把已登记文稿另存为来源任务的新草稿版本（不覆盖旧稿或成果）
  { method: 'documentsSave', http: 'POST', path: '/api/documents/save', contract: 'documents_save' },
  { method: 'source', http: 'GET', path: '/api/source', contract: 'source' },
  { method: 'search', http: 'GET', path: '/api/search', contract: 'search' },
  { method: 'getCapsules', http: 'GET', path: '/api/capsules', contract: 'capsules', noRequest: true },
  { method: 'putCapsules', http: 'PUT', path: '/api/capsules', contract: 'capsules' },
  { method: 'capsulesReset', http: 'POST', path: '/api/capsules/reset', contract: 'capsules_reset' },
  // 所外接入：GET 不带输入；POST 每次只发 code 或 enabled 中的一个动作
  { method: 'getRemoteAccess', http: 'GET', path: '/api/remote_access', contract: 'remote_access', noRequest: true },
  { method: 'postRemoteAccess', http: 'POST', path: '/api/remote_access', contract: 'remote_access' },
